def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    def is_valid_amount(token: str) -> bool:
        return len(token) > 0 and token.isdigit()

    # State: accounts dict {name: (balance, frozen)}
    accounts: dict[str, list] = {}  # name -> [balance, frozen]

    rejected = []
    # Undo stack: list of callables that revert an operation
    undo_stack = []

    for idx, op in enumerate(ops):
        tokens = op.split(' ')
        verb = tokens[0] if tokens else ''

        if verb == 'open':
            if len(tokens) != 3:
                rejected.append(idx)
                continue
            _, a, n_str = tokens
            if not is_valid_amount(n_str):
                rejected.append(idx)
                continue
            n = int(n_str)
            if n < 0:
                rejected.append(idx)
                continue
            if a in accounts:
                rejected.append(idx)
                continue
            accounts[a] = [n, False]
            def make_undo_open(name):
                def revert():
                    del accounts[name]
                return revert
            undo_stack.append(make_undo_open(a))

        elif verb == 'deposit':
            if len(tokens) != 3:
                rejected.append(idx)
                continue
            _, a, n_str = tokens
            if not is_valid_amount(n_str):
                rejected.append(idx)
                continue
            n = int(n_str)
            if n <= 0:
                rejected.append(idx)
                continue
            if a not in accounts:
                rejected.append(idx)
                continue
            accounts[a][0] += n
            def make_undo_deposit(name, amount):
                def revert():
                    accounts[name][0] -= amount
                return revert
            undo_stack.append(make_undo_deposit(a, n))

        elif verb == 'withdraw':
            if len(tokens) != 3:
                rejected.append(idx)
                continue
            _, a, n_str = tokens
            if not is_valid_amount(n_str):
                rejected.append(idx)
                continue
            n = int(n_str)
            if n <= 0:
                rejected.append(idx)
                continue
            if a not in accounts:
                rejected.append(idx)
                continue
            bal, frozen = accounts[a]
            if frozen:
                rejected.append(idx)
                continue
            if bal < n:
                rejected.append(idx)
                continue
            accounts[a][0] -= n
            def make_undo_withdraw(name, amount):
                def revert():
                    accounts[name][0] += amount
                return revert
            undo_stack.append(make_undo_withdraw(a, n))

        elif verb == 'transfer':
            if len(tokens) != 4:
                rejected.append(idx)
                continue
            _, a, b, n_str = tokens
            if not is_valid_amount(n_str):
                rejected.append(idx)
                continue
            n = int(n_str)
            if n <= 0:
                rejected.append(idx)
                continue
            if a == b:
                rejected.append(idx)
                continue
            if a not in accounts or b not in accounts:
                rejected.append(idx)
                continue
            bal_a, frozen_a = accounts[a]
            if frozen_a:
                rejected.append(idx)
                continue
            if bal_a < n:
                rejected.append(idx)
                continue
            accounts[a][0] -= n
            accounts[b][0] += n
            def make_undo_transfer(src, dst, amount):
                def revert():
                    accounts[src][0] += amount
                    accounts[dst][0] -= amount
                return revert
            undo_stack.append(make_undo_transfer(a, b, n))

        elif verb == 'freeze':
            if len(tokens) != 2:
                rejected.append(idx)
                continue
            _, a = tokens
            if a not in accounts:
                rejected.append(idx)
                continue
            if accounts[a][1]:
                rejected.append(idx)
                continue
            accounts[a][1] = True
            def make_undo_freeze(name):
                def revert():
                    accounts[name][1] = False
                return revert
            undo_stack.append(make_undo_freeze(a))

        elif verb == 'unfreeze':
            if len(tokens) != 2:
                rejected.append(idx)
                continue
            _, a = tokens
            if a not in accounts:
                rejected.append(idx)
                continue
            if not accounts[a][1]:
                rejected.append(idx)
                continue
            accounts[a][1] = False
            def make_undo_unfreeze(name):
                def revert():
                    accounts[name][1] = True
                return revert
            undo_stack.append(make_undo_unfreeze(a))

        elif verb == 'undo':
            if len(tokens) != 1:
                rejected.append(idx)
                continue
            if not undo_stack:
                rejected.append(idx)
                continue
            revert_fn = undo_stack.pop()
            revert_fn()
            # undo itself is never added to undo_stack

        else:
            rejected.append(idx)

    balances = {name: state[0] for name, state in accounts.items()}
    return balances, rejected
